INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_zem-1-domov-okoli_0','Jak se jmenuje místo, kde bydlíme?',ARRAY['domov','hřiště','les','škola']::TEXT[],0,'Domov je místo, kde žijeme.',1,ARRAY[]::TEXT[],NULL,0,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_1','V čem může rodina bydlet?',ARRAY['v autě jen','v domě nebo bytě','ve stanu na poli jen','na stromě']::TEXT[],1,'Většina lidí bydlí v domě nebo bytě.',1,ARRAY[]::TEXT[],NULL,1,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_2','Kde je zahrada?',ARRAY['v pokoji','v kuchyni','v lednici','u domu']::TEXT[],3,'Zahrada bývá u domu.',1,ARRAY[]::TEXT[],NULL,2,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_3','Jak se jmenuje ulice, kde bydlíš, v adrese?',ARRAY['barva domu','číslo boty','jméno kamaráda','název ulice']::TEXT[],3,'Adresa obsahuje ulici.',2,ARRAY[]::TEXT[],NULL,3,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_4','Co najdeme v okolí domova?',ARRAY['jen moře','jen pohoří','obchod, školu, hřiště','jen poušť']::TEXT[],2,'V okolí jsou běžná místa.',2,ARRAY[]::TEXT[],NULL,4,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_5','Kdo bydlí s tebou v domově?',ARRAY['učitelé','rodina','cizí lidé','kuchaři ze školy']::TEXT[],1,'S rodinou sdílíme domov.',2,ARRAY[]::TEXT[],NULL,5,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_6','Kde si hrajeme na čerstvém vzduchu?',ARRAY['na hřišti','v lednici','v koupelně','ve skříni']::TEXT[],0,'Hřiště je místo pro hry.',3,ARRAY[]::TEXT[],NULL,6,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_7','Kde nakupujeme potraviny?',ARRAY['na poště','ve škole','v obchodě','v knihovně']::TEXT[],2,'Potraviny kupujeme v obchodě.',3,ARRAY[]::TEXT[],NULL,7,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_8','Kam zavoláme při požáru?',ARRAY['pošťákovi','hasičům (150)','kuchaři','pekaři']::TEXT[],1,'Hasiči hasí požáry.',3,ARRAY[]::TEXT[],NULL,8,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_9','Jak poznáme, kde bydlíme?',ARRAY['podle počasí','podle oblíbené hračky','podle adresy','podle barvy aut']::TEXT[],2,'Adresa určuje místo.',4,ARRAY[]::TEXT[],NULL,9,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_10','Kde je knihovna?',ARRAY['v lese','v budově, kde se půjčují knihy','na louce','v rybníce']::TEXT[],1,'Knihovna půjčuje knihy.',4,ARRAY[]::TEXT[],NULL,10,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_11','Kdo doručuje dopisy?',ARRAY['pošťák','pekař','řidič autobusu','hasič']::TEXT[],0,'Dopisy doručuje pošťák.',4,ARRAY[]::TEXT[],NULL,11,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_12','Proč je důležité znát svou adresu?',ARRAY['aby nás kamarádi uhodli','kvůli narozeninám','abychom se mohli vrátit domů','kvůli oblíbenému jídlu']::TEXT[],2,'Adresa pomůže při ztrátě.',5,ARRAY[]::TEXT[],NULL,12,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_13','Jak se jmenuje místo, kde jsou domy, ulice a obchody?',ARRAY['les','moře','poušť','obec nebo město']::TEXT[],3,'Domy tvoří obec.',5,ARRAY[]::TEXT[],NULL,13,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_14','Co znamená mít rád svůj domov?',ARRAY['utíkat z něj','nechat ho špinavý','bát se ho','starat se o něj a cítit se tam dobře']::TEXT[],3,'Domov je důležitý.',5,ARRAY[]::TEXT[],NULL,14,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_15','Kde se obvykle připravuje jídlo?',ARRAY['v kuchyni','na zahradě','v koupelně','ve sklepě']::TEXT[],0,'V kuchyni se vaří a peče.',1,ARRAY[]::TEXT[],NULL,15,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_16','Kde si čistíme zuby?',ARRAY['v garáži','v koupelně','v kuchyni','na půdě']::TEXT[],1,'Zuby čistíme v koupelně u umyvadla.',1,ARRAY[]::TEXT[],NULL,16,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_17','Kde spíme?',ARRAY['v koupelně','v ložnici','na chodbě','v kuchyni']::TEXT[],1,'Spíme v ložnici nebo v pokoji.',1,ARRAY[]::TEXT[],NULL,17,'c_zem-1-domov-okoli',NULL,NOW()),
('q_zem-1-domov-okoli_18','Kdo se o nás doma stará?',ARRAY['cizí pán z ulice','řidič tramvaje','rodiče','pošťák']::TEXT[],2,'Rodiče se o děti starají.',1,ARRAY[]::TEXT[],NULL,18,'c_zem-1-domov-okoli',NULL,NOW()),
